package com.lamggm.rospocket;
import java.nio.*;import java.util.*;
/** Compact indexed full-geometry payload, independent of any GL context. */
final class RobotCad {
 static final int MAX_BYTES=64*1024*1024,MAX_TRIANGLES=2000000,MAX_ASSEMBLED=4000000;
 static final class Chunk {final FloatBuffer vertices;final ShortBuffer indices;final boolean embedded;Chunk(float[] v,int used,short[] i,int n,boolean e){vertices=ByteBuffer.allocateDirect(used*4).order(ByteOrder.nativeOrder()).asFloatBuffer();vertices.put(v,0,used).position(0);indices=ByteBuffer.allocateDirect(n*2).order(ByteOrder.nativeOrder()).asShortBuffer();indices.put(i,0,n).position(0);embedded=e;}}
 static final class Mesh {final List<Chunk> chunks;final int triangles;final long byteCount;final double[] min,max;Mesh(List<Chunk> c,int n,double[] low,double[] high){chunks=Collections.unmodifiableList(new ArrayList<>(c));triangles=n;min=low.clone();max=high.clone();long b=0;for(Chunk x:c)b+=x.vertices.limit()*4L+x.indices.limit()*2L;byteCount=b;}}
 static final class Part {final RobotDescription.Visual visual;final Mesh mesh;final double[] model,local;Part(RobotDescription.Visual v,Mesh m,double[] reference,double[] inLink){visual=v;mesh=m;model=reference;local=inLink;}}
 static final class Scene {final List<Part> parts;final int triangles;final double cx,cy,cz,radius;Scene(List<Part> p){parts=Collections.unmodifiableList(new ArrayList<>(p));int n=0;double[] low={Double.POSITIVE_INFINITY,Double.POSITIVE_INFINITY,Double.POSITIVE_INFINITY},hi={Double.NEGATIVE_INFINITY,Double.NEGATIVE_INFINITY,Double.NEGATIVE_INFINITY};for(Part x:p){n+=x.mesh.triangles;if(n>MAX_ASSEMBLED)throw new IllegalArgumentException("CAD excede 4 milhões de faces instanciadas");for(int c=0;c<8;c++){double[] a=RobotDescription.point(x.model,(c&1)==0?x.mesh.min[0]:x.mesh.max[0],(c&2)==0?x.mesh.min[1]:x.mesh.max[1],(c&4)==0?x.mesh.min[2]:x.mesh.max[2]);for(int k=0;k<3;k++){if(!Double.isFinite(a[k])||Math.abs(a[k])>1e8)throw new IllegalArgumentException("CAD bounds inválidos");low[k]=Math.min(low[k],a[k]);hi[k]=Math.max(hi[k],a[k]);}}}triangles=n;cx=n==0?0:(low[0]+hi[0])/2;cy=n==0?0:(low[1]+hi[1])/2;cz=n==0?0:(low[2]+hi[2])/2;radius=n==0?1:Math.max(.001,Math.sqrt(Math.pow(hi[0]-low[0],2)+Math.pow(hi[1]-low[1],2)+Math.pow(hi[2]-low[2],2))/2);}}
 static double[] inverseRigid(double[] m){if(m==null)throw new IllegalArgumentException("Link ausente");double[] out=RobotDescription.identity();for(int r=0;r<3;r++)for(int c=0;c<3;c++)out[r*4+c]=m[c*4+r];for(int r=0;r<3;r++)out[r*4+3]=-(out[r*4]*m[3]+out[r*4+1]*m[7]+out[r*4+2]*m[11]);return out;}
 static double[] scaled(double[] m,double[] s){double[] out=m.clone();for(int r=0;r<3;r++)for(int c=0;c<3;c++)out[r*4+c]*=s[c];return out;}
 static Mesh decode(byte[] bytes){return RobotGlb.decodePacked(bytes);}
}
